SELECT define_rule($r${
 "rule_id": "LSC.C.RUR_EC_SMALL_FRONT_6M",
 "instrument_version": "LSC_PLANNING_SCHEME_2018@2025-05-02",
 "topic": "SETBACK.FRONTAGE",
 "title": "Rural / Emerging community lot < 3,000 m2: standalone Class 10a (shed, garage, carport) and any other building or structure 6 m from road frontages (corner lot <= 24 m deep: primary frontage only)",
 "role": "REQUIREMENT",
 "regime": "BUILDING",
 "enforceability": "DEEMED_TO_COMPLY",
 "provision_kind": "ACCEPTABLE_OUTCOME",
