 "value": 6,
 "unit": "m",
 "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT",
 "verification": "VERIFIED_VERBATIM",
 "automatable": true,
 "scopes": [{"level":"LOCAL_GOVERNMENT","lg":"LIVINGSTONE"},{"level":"ZONE","zone":"LSC:RURAL"},{"level":"ZONE","zone":"LSC:EMERGING_COMMUNITY"}],
 "subjects": ["CLASS_10A","CLASS_10B"],
 "conditions": [[{"fact":"lot_area_m2","op":"<","value":3000},{"fact":"is_corner_lot","op":"IS_FALSE"},{"fact":"boundary_type","op":"IN","value":["PRIMARY_FRONTAGE","SECONDARY_FRONTAGE_ROAD"]}],[{"fact":"lot_area_m2","op":"<","value":3000},{"fact":"is_corner_lot","op":"IS_TRUE"},{"fact":"average_lot_depth_m","op":">","value":24},{"fact":"boundary_type","op":"IN","value":["PRIMARY_FRONTAGE","SECONDARY_FRONTAGE_ROAD"]}],[{"fact":"lot_area_m2","op":"<","value":3000},{"fact":"is_corner_lot","op":"IS_TRUE"},{"fact":"average_lot_depth_m","op":"<=","value":24},{"fact":"boundary_type","op":"=","value":"PRIMARY_FRONTAGE"}]],
 "sources": [{"key":"lsc_rur_ec_lt3000_front_class10a","role":"PRIMARY","quote":"The development is on a lot having an area 0 m2 to 2,999 m2 ... Circumstance (A): If the lot is not a corner lot, buildings or structures have a setback from road frontage lot boundaries in accordance with the following: ... (d) a standalone Class 10a building under the Building Code of Australia being a shed, garage or carport has a setback of at least six (6) metres; and (e) any other building or structure has a setback of at least six (6) metres."},{"key":"lsc_rur_ec_lt3000_front_corner_class10a","role":"SUPPLEMENTARY","quote":"(a) if the ‘depth of a lot’ has an average of greater than twenty-four (24) metres: ... (iv) a standalone Class 10a buildings under the Building Code of Australia being a shed, garage or carport has a setback of at least six (6) metres; (v) any other building or structure has a setback of at least six (6) metres; ... (b) if the ‘depth of a lot’ has an average of twenty-four (24) metres or less: (i) for the ‘primary road frontage’: ... (D) a standalone Class 10a buildings under the Building Code of Australia being a shed, garage or carport has a setback of at least six (6) metres; (E) any other building or structure has a setback of at least six (6) metres;"},{"key":"lsc_rur_ec_3000_9999_front","role":"SUPPLEMENTARY","quote":"The development is on a lot having an area from 3,000 m2 to 9,999 m2"}],
 "interpretation_notes": "Items (d) standalone Class 10a shed/garage/carport and (e) any other building or structure (both 6 m); the dwelling (3 m), decks/patios/pergolas (3 m) and attached-garage rows are outside the Class 10 scope. Non-corner lots and corner lots deeper than 24 m: all road frontages; corner lot with average depth <= 24 m: primary road frontage only - the secondary frontage limb (b)(ii) refers to Figure SC10.1.6 and was not transcribed, so the QDC stays in play there. The 9 m x 9 m corner truncation (no building or structure over 2 m) is a geometric limit for the geometry layer. Exemptions: <= 2 m structures (LSC.C.SCH10_LOW_STRUCTURE_FRONT_EXEMPT), small gatehouse/arch (LSC.C.SCH10_GATEHOUSE_FRONT_EXEMPT); open carport concession: LSC.C.RUR_EC_SMALL_OPEN_CARPORT_FRONT. Pools are not named; an in-ground pool under 2 m outermost projection height is exempt. Lot band '0 m2 to 2,999 m2' encoded as lot_area_m2 < 3000 (the next row starts at 3,000 m2). Emerging community: the table applies only outside a Local Plan or approved structure plan area (table note); approved structure plans are not modelled. Yaamba Historic Township Precinct: displaced by LSC.C.YAAMBA_* (OVERRIDES).",
 "effective_from": "2025-05-02"}$r$);
SELECT supersede_draft('LSC.C.RUR_EC_SMALL_FRONT_6M@2025-05-02', 'LSC.lsc_rur_ec_lt3000_front_class10a');
SELECT supersede_draft('LSC.C.RUR_EC_SMALL_FRONT_6M@2025-05-02', 'LSC.lsc_rur_ec_lt3000_front_corner_class10a');
