SELECT define_rule($r${
 "rule_id": "LSC.C.RUR_EC_SMALL_SIDE_REAR_NARROW",
 "instrument_version": "LSC_PLANNING_SCHEME_2018@2025-05-02",
 "topic": "SETBACK.SIDE_REAR",
 "title": "Rural / Emerging community lot < 3,000 m2: side and rear setback, rectangular or near rectangular lot with road frontage <= 15 m (Table SC10.1.9 by frontage and outermost projection height)",
 "role": "REQUIREMENT",
 "regime": "BUILDING",
 "enforceability": "DEEMED_TO_COMPLY",
 "provision_kind": "ACCEPTABLE_OUTCOME",
 "measurement": "SCHEME_SETBACK_SIDE",
 "operator": ">=",
 "value": {"op":"case","when":[{"if":{"op":"<=","args":[{"var":"part_height_m"},4.5]},"then":{"op":"case","when":[{"if":{"op":"<=","args":[{"var":"road_frontage_m"},10.5]},"then":0.75},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},11]},"then":0.825},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},11.5]},"then":0.9},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},12]},"then":0.975},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},12.5]},"then":1.05},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},13]},"then":1.125},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},13.5]},"then":1.2},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},14]},"then":1.275},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},14.5]},"then":1.35}],"else":1.425}},{"if":{"op":"<=","args":[{"var":"part_height_m"},7.5]},"then":{"op":"case","when":[{"if":{"op":"<=","args":[{"var":"road_frontage_m"},10.5]},"then":1},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},11]},"then":1.1},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},11.5]},"then":1.2},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},12]},"then":1.3},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},12.5]},"then":1.4},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},13]},"then":1.5},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},13.5]},"then":1.6},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},14]},"then":1.7},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},14.5]},"then":1.8}],"else":1.9}}],"else":{"op":"+","args":[2,{"op":"*","args":[0.5,{"op":"ceil","args":[{"op":"/","args":[{"op":"-","args":[{"var":"part_height_m"},7.5]},3]}]}]}]}},
 "unit": "m",
 "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT",
 "verification": "VERIFIED_VERBATIM",
 "automatable": false,
 "scopes": [{"level":"LOCAL_GOVERNMENT","lg":"LIVINGSTONE"},{"level":"ZONE","zone":"LSC:RURAL"},{"level":"ZONE","zone":"LSC:EMERGING_COMMUNITY"}],
 "subjects": ["ANY"],
 "conditions": [[{"fact":"lot_area_m2","op":"<","value":3000},{"fact":"road_frontage_m","op":"<=","value":15},{"fact":"lot_is_rectangular_or_near","op":"IS_TRUE"},{"fact":"boundary_type","op":"IN","value":["SIDE","REAR"]}]],
 "sources": [{"key":"lsc_rur_ec_lt3000_side_rear_frontage_le15","role":"PRIMARY","quote":"The development is on a lot having an area 0 m2 to 2,999 m2 ... Circumstance (A): If the lot is rectangular or near rectangular with a road frontage of fifteen (15) metres or less, the setback for the building or structure is in accordance with Table SC10.1.9. ... Table SC10.1.9: Side and rear lot boundary setbacks where lot road frontages are fifteen metres or less | Road Frontage (in metres) | Side and Rear Boundary Setback (in metres) | At any point where the ‘outermost projection height’ is between 2 metres and 4.5 metres | At any point where the ‘outermost projection height’ is 4.501 metres to 7.5 metres | At any point where the ‘outermost projection height’ is greater than 7.5 metres || 14.501 – 15.000 | 1.425 | 1.900 || 14.001 – 14.500 | 1.350 | 1.800 || 13.501 – 14.000 | 1.275 | 1.700 || 13.001 – 13.500 | 1.200 | 1.600 || 12.501 – 13.000 | 1.125 | 1.500 || 12.001 – 12.500 | 1.050 | 1.400 || 11.501 – 12.000 | 0.975 | 1.300 || 11.001 – 11.500 | 0.900 | 1.200 || 10.501 – 11.000 | 0.825 | 1.100 || 10.500 or less | 0.750 | 1.000 || 2 metres plus 0.5 of a metre for every 3 metres or part of 3 metres by which the height exceeds 7.5 metres."},{"key":"lsc_rur_ec_3000_9999_front","role":"SUPPLEMENTARY","quote":"The development is on a lot having an area from 3,000 m2 to 9,999 m2"}],
 "interpretation_notes": "Evaluated per part: part_height_m = the 'outermost projection height' at that point (SC1.2). Rows 'x.001 - y.000' encoded as road_frontage_m <= y. The table starts at 2 m; whole structures not over 2 m are exempt (LSC.C.SCH10_LOW_STRUCTURE_SIDE_REAR_EXEMPT); parts under 2 m of a taller structure take the first band. 'Rectangular or near rectangular' is a judgement => not automatable. A non-rectangular lot with frontage <= 15 m falls in neither Circumstance (A) nor (B) (gap in the scheme). Class 10a within the setback: LSC.C.RUR_EC_SMALL_CLASS10A_BTB; rainwater tank / ornamental pergola exemptions apply. Lot band '0 m2 to 2,999 m2' encoded as lot_area_m2 < 3000 (the next row starts at 3,000 m2). Emerging community: the table applies only outside a Local Plan or approved structure plan area (table note); approved structure plans are not modelled. Yaamba Historic Township Precinct: displaced by LSC.C.YAAMBA_* (OVERRIDES).",
 "effective_from": "2025-05-02"}$r$);
SELECT supersede_draft('LSC.C.RUR_EC_SMALL_SIDE_REAR_NARROW@2025-05-02', 'LSC.lsc_rur_ec_lt3000_side_rear_frontage_le15');
SELECT alt_overrides('LSC.C.RUR_EC_SMALL_SIDE_REAR_NARROW@2025-05-02', ARRAY['QDC12.A2a.SIDE_REAR_CLEARANCE','QDC11.A2a.SIDE_REAR_CLEARANCE','QDC12.A2b.NARROW_LOT_CLEARANCE','QDC11.A2b.NARROW_LOT_CLEARANCE','QDC12.A2d.CLASS10A_WITHIN_CLEARANCE','QDC11.A2d.CLASS10A_WITHIN_CLEARANCE'], 'Part 1 s1.6(3) and (4)(c): Rural zone code AO5.1 / Emerging community zone code AO5.1 (Table SC10.1.1) is a building assessment provision (s33 alternative boundary clearance for Class 1 and 10); Table 5.6.1 makes standalone Class 10a building work accepted subject to requirements against it. Circumstance (C) sets its own Class 10a concession, displacing QDC A2(d).');

