 "subjects": ["CLASS_10A"],
 "conditions": [[{"fact":"lot_area_m2","op":"<","value":3000},{"fact":"boundary_type","op":"IN","value":["SIDE","REAR"]},{"fact":"part_height_m","op":"<=","value":4.5},{"fact":"mean_height_m","op":"<=","value":3.5},{"fact":"btb_length_on_boundary_m","op":"<=","value":9},{"fact":"distance_to_adjoining_habitable_window_m","op":">=","value":1.5}]],
 "sources": [{"key":"lsc_rur_ec_lt3000_side_rear_class10a_concession","role":"PRIMARY","quote":"Circumstance (C): If a Class 10a building or part as defined under the Building Code of Australia, the building or part may be within the side and rear setbacks identified in Table SC10.1.9 or Table SC10.1.10 only if: (a) the ‘outermost projection height’ is not more than 4.5 metres, and the building or structure has a ‘mean height’ of not more than 3.5 metres; and (b) the total length of all buildings or parts, of any class, within the setback is not more than nine (9) metres along any one boundary; and (c) the Class 10a buildings or parts within the setback are located no closer than 1.5 metre to a required window in a habitable room of an adjoining dwelling."}],
 "interpretation_notes": "Circumstance (C) states no minimum distance for a conforming Class 10a part, so it may be built to the boundary (value 0). part_height_m = outermost projection height of the part within the setback. btb_length_on_boundary_m counts all buildings or parts of any class within the setback along that boundary. 'Required window in a habitable room' read as the habitable-room window fact. Lot band '0 m2 to 2,999 m2' encoded as lot_area_m2 < 3000 (the next row starts at 3,000 m2). Emerging community: the table applies only outside a Local Plan or approved structure plan area (table note); approved structure plans are not modelled. Yaamba Historic Township Precinct: displaced by LSC.C.YAAMBA_* (OVERRIDES).",
 "effective_from": "2025-05-02"}$r$);
