 "regime": "BUILDING",
 "enforceability": "DEEMED_TO_COMPLY",
 "provision_kind": "ACCEPTABLE_OUTCOME",
 "measurement": "SCHEME_SETBACK_SIDE",
 "operator": ">=",
 "value": {"op":"case","when":[{"if":{"op":"<=","args":[{"var":"part_height_m"},4.5]},"then":1.5},{"if":{"op":"<=","args":[{"var":"part_height_m"},7.5]},"then":2}],"else":{"op":"+","args":[2,{"op":"*","args":[0.5,{"op":"ceil","args":[{"op":"/","args":[{"op":"-","args":[{"var":"part_height_m"},7.5]},3]}]}]}]}},
 "unit": "m",
 "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT",
 "verification": "VERIFIED_VERBATIM",
 "automatable": true,
 "scopes": [{"level":"LOCAL_GOVERNMENT","lg":"LIVINGSTONE"},{"level":"ZONE","zone":"LSC:LOW_DENSITY_RESIDENTIAL"},{"level":"ZONE","zone":"LSC:LOW_MEDIUM_DENSITY_RESIDENTIAL"},{"level":"ZONE","zone":"LSC:TOWNSHIP"}],
 "subjects": ["ANY"],
 "conditions": [[{"fact":"road_frontage_m","op":">","value":15},{"fact":"boundary_type","op":"IN","value":["SIDE","REAR"]}]],
 "sources": [{"key":"lsc_ldr_lmdr_twp_side_rear_frontage_gt15","role":"PRIMARY","quote":"All lot sizes ... Circumstance (B): If the lot has a road frontage greater than fifteen (15) metres, the setback for a part of the building or structure is in accordance with Table SC10.1.10. ... Table SC10.1.10: Side and rear lot boundary setbacks where lot road frontages are greater than fifteen metres | Road Frontage (in metres) | Side and Rear Boundary Setback (in metres) | At any point where the ‘outermost projection height’ is between 2 metres and 4.5 metres | At any point where the ‘outermost projection height’ is 4.501 metres to 7.5 metres | At any point where the ‘outermost projection height’ is greater than 7.5 metres || 15.001 or greater | 1.5 metres | 2 metres | 2 metres plus 0.5 of a metre for every 3 metres or part of 3 metres by which the height exceeds 7.5 metres."}],
 "interpretation_notes": "Evaluated per part: part_height_m = the 'outermost projection height' at that point (SC1.2); 'every 3 metres or part of 3 metres' => ceil. Whole structures not over 2 m are exempt (LSC.C.SCH10_LOW_STRUCTURE_SIDE_REAR_EXEMPT); parts under 2 m of a taller structure take the first band. Class 10a within the setback: LSC.C.LDR_LMDR_TWP_CLASS10A_BTB.",
 "effective_from": "2025-05-02"}$r$);
SELECT supersede_draft('LSC.C.LDR_LMDR_TWP_SIDE_REAR_WIDE@2025-05-02', 'LSC.lsc_ldr_lmdr_twp_side_rear_frontage_gt15');
SELECT alt_overrides('LSC.C.LDR_LMDR_TWP_SIDE_REAR_WIDE@2025-05-02', ARRAY['QDC12.A2a.SIDE_REAR_CLEARANCE','QDC11.A2a.SIDE_REAR_CLEARANCE','QDC12.A2b.NARROW_LOT_CLEARANCE','QDC11.A2b.NARROW_LOT_CLEARANCE','QDC12.A2d.CLASS10A_WITHIN_CLEARANCE','QDC11.A2d.CLASS10A_WITHIN_CLEARANCE'], 'Part 1 s1.6(3) and (4)(c): Low density residential zone code AO3.2, Low-medium density residential and Township zone codes AO2.2 (Table SC10.1.2) is a building assessment provision (s33 alternative boundary clearance for Class 1 and 10); Table 5.6.1 makes standalone Class 10a building work accepted subject to requirements against it. Circumstance (C) sets its own Class 10a concession, displacing QDC A2(d).');

SELECT define_rule($r${
 "rule_id": "LSC.C.LDR_LMDR_TWP_CLASS10A_BTB",
 "instrument_version": "LSC_PLANNING_SCHEME_2018@2025-05-02",
 "topic": "SETBACK.SIDE_REAR.BTB",
 "title": "Low density / Low-medium density residential / Township: Class 10a building or part may be within the side and rear setback (outermost projection height <= 4.5 m, mean height <= 3.5 m, <= 9 m along any one boundary, >= 1.5 m from a neighbour's habitable-room window)",
 "role": "RELAXATION",
 "regime": "BUILDING",
 "enforceability": "DEEMED_TO_COMPLY",
 "provision_kind": "ACCEPTABLE_OUTCOME",
 "measurement": "SCHEME_SETBACK_SIDE",
 "operator": ">=",
 "value": 0,
 "unit": "m",
 "permits_btb": true,
 "verification": "VERIFIED_VERBATIM",
 "automatable": true,
 "scopes": [{"level":"LOCAL_GOVERNMENT","lg":"LIVINGSTONE"},{"level":"ZONE","zone":"LSC:LOW_DENSITY_RESIDENTIAL"},{"level":"ZONE","zone":"LSC:LOW_MEDIUM_DENSITY_RESIDENTIAL"},{"level":"ZONE","zone":"LSC:TOWNSHIP"}],
 "subjects": ["CLASS_10A"],
 "conditions": [[{"fact":"boundary_type","op":"IN","value":["SIDE","REAR"]},{"fact":"part_height_m","op":"<=","value":4.5},{"fact":"mean_height_m","op":"<=","value":3.5},{"fact":"btb_length_on_boundary_m","op":"<=","value":9},{"fact":"distance_to_adjoining_habitable_window_m","op":">=","value":1.5}]],
 "sources": [{"key":"lsc_ldr_lmdr_twp_side_rear_class10a_concession","role":"PRIMARY","quote":"Circumstance (C): If a Class 10a building or part as defined under the Building Code of Australia, the building or part may be within the side and rear setbacks identified in Table SC10.1.9 or Table SC10.1.10 only if: (a) the ‘outermost projection height’ is not more than 4.5 metres, and the building or structure has a ‘mean height’ of not more than 3.5 metres; and (b) the total length of all buildings or parts, of any class, within the setback is not more than nine (9) metres along any one boundary; and (c) the Class 10a buildings or parts within the setback are located no closer than 1.5 metre to a required window in a habitable room of an adjoining dwelling."}],
 "interpretation_notes": "Circumstance (C) states no minimum distance for a conforming Class 10a part, so it may be built to the boundary (value 0). part_height_m = outermost projection height of the part within the setback. btb_length_on_boundary_m counts all buildings or parts of any class within the setback along that boundary. 'Required window in a habitable room' read as the habitable-room window fact.",
 "effective_from": "2025-05-02"}$r$);
SELECT supersede_draft('LSC.C.LDR_LMDR_TWP_CLASS10A_BTB@2025-05-02', 'LSC.lsc_ldr_lmdr_twp_side_rear_class10a_concession');
