SELECT define_rule($r${
 "rule_id": "LSC.C.MDR_MT_OPEN_CARPORT_FRONT",
 "instrument_version": "LSC_PLANNING_SCHEME_2018@2025-05-02",
 "topic": "SETBACK.FRONTAGE",
 "title": "Medium density residential / Major tourism (Capricorn International Resort and Great Keppel Island precincts): one open carport may be within the road frontage setback with supporting posts >= 1 m from the road boundary (<= 3.5 m high, <= 7 m wide, supports <= 15% of perimeter)",
 "role": "RELAXATION",
 "regime": "BUILDING",
 "enforceability": "DEEMED_TO_COMPLY",
 "provision_kind": "ACCEPTABLE_OUTCOME",
 "measurement": "SCHEME_SETBACK_FRONT",
 "operator": ">=",
 "value": 1,
 "unit": "m",
 "verification": "VERIFIED_VERBATIM",
 "automatable": false,
 "scopes": [{"level":"LOCAL_GOVERNMENT","lg":"LIVINGSTONE"},{"level":"ZONE","zone":"LSC:MEDIUM_DENSITY_RESIDENTIAL"},{"level":"PRECINCT","precinct":"LSC:MAJOR_TOURISM/CAPRICORN_INTERNATIONAL_RESORT"},{"level":"PRECINCT","precinct":"LSC:MAJOR_TOURISM/GREAT_KEPPEL_ISLAND"}],
 "subjects": ["OPEN_CARPORT"],
 "conditions": [[{"fact":"structure_height_m","op":"<=","value":10},{"fact":"boundary_type","op":"IN","value":["PRIMARY_FRONTAGE","SECONDARY_FRONTAGE_ROAD"]},{"fact":"structure_height_m","op":"<=","value":3.5},{"fact":"livingstone_open_carport_width_m","op":"<=","value":7},{"fact":"carport_obstruction_pct","op":"<=","value":15}]],
 "sources": [{"key":"lsc_mdr_mt_front_open_carport","role":"PRIMARY","quote":"Circumstance (C): If a shade sail or an ‘open carport’, the shade sail or ‘open car port’ may have a road frontage lot boundary setback that is less than the setback specified in Circumstance (A) or Circumstance (B) only if: ... (c) the height of the shade sail or open carport does not exceed 3.5 metres above ground level to the apex; (d) the maximum width is the lesser of seven (7) metres or fifty (50) per centum of the width of the road frontage from which vehicle access is obtained (measured from the inside of the outermost supporting posts); (e) supporting posts have a setback of at least one (1) metre from any road frontage lot boundary; ... (g) the sum perimeter dimension of supports located within the setback does not exceed fifteen (15) per centum of the total perimeter dimension"}],
 "interpretation_notes": "Circumstance (C). Value = the 1 m minimum to the supporting posts. Not encoded (so not automatable): the 50% of vehicle-access frontage limb of the width limit, 'no more than one non-compliant shade sail or open carport per lot', the 9 m x 9 m corner truncation, and zero enclosing/screening elements along the lines of supports. Shade sails are not a modelled structure type. 'Open carport' (SC1.2): two or more sides open and not less than one-third of the perimeter open. Table SC10.1.3 first row (outermost projection height <= 10 m) only; the > 10 m row was not transcribed by the research (not reached by Class 10).",
 "effective_from": "2025-05-02"}$r$);
SELECT supersede_draft('LSC.C.MDR_MT_OPEN_CARPORT_FRONT@2025-05-02', 'LSC.lsc_mdr_mt_front_open_carport');
