SELECT define_rule($r${
 "rule_id": "LSC.C.MDR_MT_SIDE_REAR_NARROW",
 "instrument_version": "LSC_PLANNING_SCHEME_2018@2025-05-02",
 "topic": "SETBACK.SIDE_REAR",
 "title": "Medium density residential / Major tourism (Capricorn International Resort and Great Keppel Island precincts): side and rear setback, rectangular or near rectangular lot with road frontage <= 15 m (Table SC10.1.9 by frontage and outermost projection height)",
 "role": "REQUIREMENT",
 "regime": "BUILDING",
 "enforceability": "DEEMED_TO_COMPLY",
 "provision_kind": "ACCEPTABLE_OUTCOME",
 "measurement": "SCHEME_SETBACK_SIDE",
 "operator": ">=",
 "value": {"op":"case","when":[{"if":{"op":"<=","args":[{"var":"part_height_m"},4.5]},"then":{"op":"case","when":[{"if":{"op":"<=","args":[{"var":"road_frontage_m"},10.5]},"then":0.75},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},11]},"then":0.825},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},11.5]},"then":0.9},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},12]},"then":0.975},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},12.5]},"then":1.05},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},13]},"then":1.125},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},13.5]},"then":1.2},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},14]},"then":1.275},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},14.5]},"then":1.35}],"else":1.425}},{"if":{"op":"<=","args":[{"var":"part_height_m"},7.5]},"then":{"op":"case","when":[{"if":{"op":"<=","args":[{"var":"road_frontage_m"},10.5]},"then":1},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},11]},"then":1.1},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},11.5]},"then":1.2},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},12]},"then":1.3},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},12.5]},"then":1.4},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},13]},"then":1.5},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},13.5]},"then":1.6},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},14]},"then":1.7},{"if":{"op":"<=","args":[{"var":"road_frontage_m"},14.5]},"then":1.8}],"else":1.9}}],"else":{"op":"+","args":[2,{"op":"*","args":[0.5,{"op":"ceil","args":[{"op":"/","args":[{"op":"-","args":[{"var":"part_height_m"},7.5]},3]}]}]}]}},
 "unit": "m",
 "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT",
 "verification": "VERIFIED_VERBATIM",
 "automatable": false,
 "scopes": [{"level":"LOCAL_GOVERNMENT","lg":"LIVINGSTONE"},{"level":"ZONE","zone":"LSC:MEDIUM_DENSITY_RESIDENTIAL"},{"level":"PRECINCT","precinct":"LSC:MAJOR_TOURISM/CAPRICORN_INTERNATIONAL_RESORT"},{"level":"PRECINCT","precinct":"LSC:MAJOR_TOURISM/GREAT_KEPPEL_ISLAND"}],
 "subjects": ["ANY"],
 "conditions": [[{"fact":"structure_height_m","op":"<=","value":10},{"fact":"road_frontage_m","op":"<=","value":15},{"fact":"lot_is_rectangular_or_near","op":"IS_TRUE"},{"fact":"boundary_type","op":"IN","value":["SIDE","REAR"]}]],
 "sources": [{"key":"lsc_mdr_mt_side_rear_frontage_le15","role":"PRIMARY","quote":"Development having an ‘outermost projection height’ equal to or below ten (10) metres located on any lot size. ... Circumstance (A): If the lot is rectangular or near rectangular with a road frontage of fifteen (15) metres or less, the setback for a part of the building or structure is in accordance with Table SC10.1.9. ... Table SC10.1.9: Side and rear lot boundary setbacks where lot road frontages are fifteen metres or less | Road Frontage (in metres) | Side and Rear Boundary Setback (in metres) | At any point where the ‘outermost projection height’ is between 2 metres and 4.5 metres | At any point where the ‘outermost projection height’ is 4.501 metres to 7.5 metres | At any point where the ‘outermost projection height’ is greater than 7.5 metres || 14.501 – 15.000 | 1.425 | 1.900 || 14.001 – 14.500 | 1.350 | 1.800 || 13.501 – 14.000 | 1.275 | 1.700 || 13.001 – 13.500 | 1.200 | 1.600 || 12.501 – 13.000 | 1.125 | 1.500 || 12.001 – 12.500 | 1.050 | 1.400 || 11.501 – 12.000 | 0.975 | 1.300 || 11.001 – 11.500 | 0.900 | 1.200 || 10.501 – 11.000 | 0.825 | 1.100 || 10.500 or less | 0.750 | 1.000 || 2 metres plus 0.5 of a metre for every 3 metres or part of 3 metres by which the height exceeds 7.5 metres."}],
 "interpretation_notes": "Evaluated per part: part_height_m = the 'outermost projection height' at that point (SC1.2). Rows 'x.001 - y.000' encoded as road_frontage_m <= y. The table starts at 2 m; whole structures not over 2 m are exempt (LSC.C.SCH10_LOW_STRUCTURE_SIDE_REAR_EXEMPT); parts under 2 m of a taller structure take the first band. 'Rectangular or near rectangular' is a judgement => not automatable. A non-rectangular lot with frontage <= 15 m falls in neither Circumstance (A) nor (B) (gap in the scheme). Class 10a within the setback: LSC.C.MDR_MT_CLASS10A_BTB; rainwater tank / ornamental pergola exemptions apply. Table SC10.1.3 first row (outermost projection height <= 10 m) only; the > 10 m row was not transcribed by the research (not reached by Class 10).",
 "effective_from": "2025-05-02"}$r$);
SELECT supersede_draft('LSC.C.MDR_MT_SIDE_REAR_NARROW@2025-05-02', 'LSC.lsc_mdr_mt_side_rear_frontage_le15');
SELECT alt_overrides('LSC.C.MDR_MT_SIDE_REAR_NARROW@2025-05-02', ARRAY['QDC12.A2a.SIDE_REAR_CLEARANCE','QDC11.A2a.SIDE_REAR_CLEARANCE','QDC12.A2b.NARROW_LOT_CLEARANCE','QDC11.A2b.NARROW_LOT_CLEARANCE','QDC12.A2d.CLASS10A_WITHIN_CLEARANCE','QDC11.A2d.CLASS10A_WITHIN_CLEARANCE'], 'Part 1 s1.6(3) and (4)(c): Medium density residential zone code AO2.2, Major tourism zone code AO2.1 / AO4.2 (Table SC10.1.3) is a building assessment provision (s33 alternative boundary clearance for Class 1 and 10); Table 5.6.1 makes standalone Class 10a building work accepted subject to requirements against it. Circumstance (C) sets its own Class 10a concession, displacing QDC A2(d).');

SELECT define_rule($r${
 "rule_id": "LSC.C.MDR_MT_SIDE_REAR_WIDE",
 "instrument_version": "LSC_PLANNING_SCHEME_2018@2025-05-02",
 "topic": "SETBACK.SIDE_REAR",
 "title": "Medium density residential / Major tourism (Capricorn International Resort and Great Keppel Island precincts): side and rear setback, road frontage > 15 m (Table SC10.1.10: 1.5 / 2 m / +0.5 per 3 m over 7.5 m)",
 "role": "REQUIREMENT",
 "regime": "BUILDING",
 "enforceability": "DEEMED_TO_COMPLY",
 "provision_kind": "ACCEPTABLE_OUTCOME",
 "measurement": "SCHEME_SETBACK_SIDE",
 "operator": ">=",
 "value": {"op":"case","when":[{"if":{"op":"<=","args":[{"var":"part_height_m"},4.5]},"then":1.5},{"if":{"op":"<=","args":[{"var":"part_height_m"},7.5]},"then":2}],"else":{"op":"+","args":[2,{"op":"*","args":[0.5,{"op":"ceil","args":[{"op":"/","args":[{"op":"-","args":[{"var":"part_height_m"},7.5]},3]}]}]}]}},
 "unit": "m",
 "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT",
 "verification": "VERIFIED_VERBATIM",
 "automatable": true,
 "scopes": [{"level":"LOCAL_GOVERNMENT","lg":"LIVINGSTONE"},{"level":"ZONE","zone":"LSC:MEDIUM_DENSITY_RESIDENTIAL"},{"level":"PRECINCT","precinct":"LSC:MAJOR_TOURISM/CAPRICORN_INTERNATIONAL_RESORT"},{"level":"PRECINCT","precinct":"LSC:MAJOR_TOURISM/GREAT_KEPPEL_ISLAND"}],
 "subjects": ["ANY"],
 "conditions": [[{"fact":"structure_height_m","op":"<=","value":10},{"fact":"road_frontage_m","op":">","value":15},{"fact":"boundary_type","op":"IN","value":["SIDE","REAR"]}]],
 "sources": [{"key":"lsc_mdr_mt_side_rear_frontage_gt15","role":"PRIMARY","quote":"Development having an ‘outermost projection height’ equal to or below ten (10) metres located on any lot size. ... Circumstance (B): If the lot has a road frontage greater than fifteen (15) metres, the setback for a part of the building or structure is in accordance with Table SC10.1.10. ... Table SC10.1.10: Side and rear lot boundary setbacks where lot road frontages are greater than fifteen metres | Road Frontage (in metres) | Side and Rear Boundary Setback (in metres) | At any point where the ‘outermost projection height’ is between 2 metres and 4.5 metres | At any point where the ‘outermost projection height’ is 4.501 metres to 7.5 metres | At any point where the ‘outermost projection height’ is greater than 7.5 metres || 15.001 or greater | 1.5 metres | 2 metres | 2 metres plus 0.5 of a metre for every 3 metres or part of 3 metres by which the height exceeds 7.5 metres."}],
 "interpretation_notes": "Evaluated per part: part_height_m = the 'outermost projection height' at that point (SC1.2); 'every 3 metres or part of 3 metres' => ceil. Whole structures not over 2 m are exempt (LSC.C.SCH10_LOW_STRUCTURE_SIDE_REAR_EXEMPT); parts under 2 m of a taller structure take the first band. Class 10a within the setback: LSC.C.MDR_MT_CLASS10A_BTB. Table SC10.1.3 first row (outermost projection height <= 10 m) only; the > 10 m row was not transcribed by the research (not reached by Class 10).",
 "effective_from": "2025-05-02"}$r$);
SELECT supersede_draft('LSC.C.MDR_MT_SIDE_REAR_WIDE@2025-05-02', 'LSC.lsc_mdr_mt_side_rear_frontage_gt15');
SELECT alt_overrides('LSC.C.MDR_MT_SIDE_REAR_WIDE@2025-05-02', ARRAY['QDC12.A2a.SIDE_REAR_CLEARANCE','QDC11.A2a.SIDE_REAR_CLEARANCE','QDC12.A2b.NARROW_LOT_CLEARANCE','QDC11.A2b.NARROW_LOT_CLEARANCE','QDC12.A2d.CLASS10A_WITHIN_CLEARANCE','QDC11.A2d.CLASS10A_WITHIN_CLEARANCE'], 'Part 1 s1.6(3) and (4)(c): Medium density residential zone code AO2.2, Major tourism zone code AO2.1 / AO4.2 (Table SC10.1.3) is a building assessment provision (s33 alternative boundary clearance for Class 1 and 10); Table 5.6.1 makes standalone Class 10a building work accepted subject to requirements against it. Circumstance (C) sets its own Class 10a concession, displacing QDC A2(d).');

SELECT define_rule($r${
 "rule_id": "LSC.C.MDR_MT_CLASS10A_BTB",
 "instrument_version": "LSC_PLANNING_SCHEME_2018@2025-05-02",
 "topic": "SETBACK.SIDE_REAR.BTB",
 "title": "Medium density residential / Major tourism (Capricorn International Resort and Great Keppel Island precincts): Class 10a building or part may be within the side and rear setback (outermost projection height <= 4.5 m, mean height <= 3.5 m, <= 9 m along any one boundary, >= 1.5 m from a neighbour's habitable-room window)",
 "role": "RELAXATION",
 "regime": "BUILDING",
 "enforceability": "DEEMED_TO_COMPLY",
 "provision_kind": "ACCEPTABLE_OUTCOME",
 "measurement": "SCHEME_SETBACK_SIDE",
 "operator": ">=",
 "value": 0,
 "unit": "m",
 "permits_btb": true,
 "verification": "VERIFIED_VERBATIM",
 "automatable": true,
 "scopes": [{"level":"LOCAL_GOVERNMENT","lg":"LIVINGSTONE"},{"level":"ZONE","zone":"LSC:MEDIUM_DENSITY_RESIDENTIAL"},{"level":"PRECINCT","precinct":"LSC:MAJOR_TOURISM/CAPRICORN_INTERNATIONAL_RESORT"},{"level":"PRECINCT","precinct":"LSC:MAJOR_TOURISM/GREAT_KEPPEL_ISLAND"}],
 "subjects": ["CLASS_10A"],
 "conditions": [[{"fact":"structure_height_m","op":"<=","value":10},{"fact":"boundary_type","op":"IN","value":["SIDE","REAR"]},{"fact":"part_height_m","op":"<=","value":4.5},{"fact":"mean_height_m","op":"<=","value":3.5},{"fact":"btb_length_on_boundary_m","op":"<=","value":9},{"fact":"distance_to_adjoining_habitable_window_m","op":">=","value":1.5}]],
 "sources": [{"key":"lsc_mdr_mt_side_rear_class10a_concession","role":"PRIMARY","quote":"Circumstance (C): If a Class 10a building or part as defined under the Building Code of Australia, the building or part may be within the side and rear setbacks identified in Table SC10.1.9 or Table SC10.1.10 only if: (a) the ‘outermost projection height’ is not more than 4.5 metres, and the building or structure has a ‘mean height’ of not more than 3.5 metres; and (b) the total length of all buildings or parts, of any class, within the setback is not more than nine (9) metres along any one boundary; and (c) the Class 10a buildings or parts within the setback are located no closer than 1.5 metre to a required window in a habitable room of an adjoining dwelling."}],
 "interpretation_notes": "Circumstance (C) states no minimum distance for a conforming Class 10a part, so it may be built to the boundary (value 0). part_height_m = outermost projection height of the part within the setback. btb_length_on_boundary_m counts all buildings or parts of any class within the setback along that boundary. 'Required window in a habitable room' read as the habitable-room window fact. Table SC10.1.3 first row (outermost projection height <= 10 m) only; the > 10 m row was not transcribed by the research (not reached by Class 10).",
 "effective_from": "2025-05-02"}$r$);
SELECT supersede_draft('LSC.C.MDR_MT_CLASS10A_BTB@2025-05-02', 'LSC.lsc_mdr_mt_side_rear_class10a_concession');
SELECT relate('LSC.C.MDR_MT_CLASS10A_BTB@2025-05-02', 'LSC.C.MDR_MT_SIDE_REAR_NARROW@2025-05-02', 'RELAXES', NULL, NULL, 'VERIFIED_VERBATIM');
SELECT relate('LSC.C.MDR_MT_CLASS10A_BTB@2025-05-02', 'LSC.C.MDR_MT_SIDE_REAR_WIDE@2025-05-02', 'RELAXES', NULL, NULL, 'VERIFIED_VERBATIM');

