-- ========== Rural zone - Yaamba Historic Township Precinct (AO10.1)
SELECT define_rule($r${
 "rule_id": "LSC.C.YAAMBA_FRONT_20M",
 "instrument_version": "LSC_PLANNING_SCHEME_2018@2025-05-02",
 "topic": "SETBACK.FRONTAGE",
 "title": "Yaamba Historic Township Precinct: buildings or structures 20 m from road frontages (+0.3 m per metre over 4.5 m)",
 "role": "REQUIREMENT",
 "regime": "BUILDING",
 "enforceability": "DEEMED_TO_COMPLY",
 "provision_kind": "ACCEPTABLE_OUTCOME",
 "measurement": "SCHEME_SETBACK_FRONT",
 "operator": ">=",
 "value": {"op":"case","when":[{"if":{"op":"<=","args":[{"var":"part_height_m"},4.5]},"then":20}],"else":{"op":"+","args":[20,{"op":"*","args":[0.3,{"op":"ceil","args":[{"op":"-","args":[{"var":"part_height_m"},4.5]}]}]}]}},
 "unit": "m",
 "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT",
 "verification": "VERIFIED_VERBATIM",
 "automatable": true,
 "scopes": [{"level":"LOCAL_GOVERNMENT","lg":"LIVINGSTONE"},{"level":"PRECINCT","precinct":"LSC:RURAL/YAAMBA_HISTORIC_TOWNSHIP"}],
 "subjects": ["ANY"],
 "conditions": [[{"fact":"structure_height_m","op":">","value":2},{"fact":"boundary_type","op":"IN","value":["PRIMARY_FRONTAGE","SECONDARY_FRONTAGE_ROAD"]}]],
 "sources": [{"key":"lsc_rur_yaamba_front","role":"PRIMARY","quote":"Where located in the Yaamba Historic Township Precinct ... (a) at any point where the ‘outermost projection height’ is between two (2) metres and 4.5 metres, a setback of at least twenty (20) metres; or (b) at any point where the ‘outermost projection height’ is greater than 4.5 metres, a setback of at least twenty (20) metres plus 0.3 of a metre for every additional metre or part thereof in height over 4.5 metres."}],
 "interpretation_notes": "Per part: part_height_m = outermost projection height; 'every additional metre or part thereof' => ceil. AO10.1 sets no requirement below 2 m outermost projection height: encoded by applying the rule only to structures over 2 m (structure_height_m > 2); a part under 2 m of a taller structure takes the 20 m band. Prevails over the Rural zone AO5.1 / Schedule 10 rules (AO5.1 applies outside this precinct) => OVERRIDES every LSC.C rule scoped to the Rural zone. Table 5.6.1 applies AO10.1 to standalone Class 10a building work in the precinct. 'Road frontage lot boundaries' => primary and secondary road frontages.",
 "effective_from": "2025-05-02"}$r$);
SELECT supersede_draft('LSC.C.YAAMBA_FRONT_20M@2025-05-02', 'LSC.lsc_rur_yaamba_front');
SELECT alt_overrides('LSC.C.YAAMBA_FRONT_20M@2025-05-02', ARRAY['QDC12.A1a.ROAD_SETBACK','QDC11.A1a.FRONTAGE_SETBACK'], 'Part 1 s1.6(3) and (4)(c): Rural zone code AO10.1 (Yaamba Historic Township Precinct) is a building assessment provision (s33 alternative boundary clearance for Class 1 and 10); Table 5.6.1 makes standalone Class 10a building work accepted subject to requirements against it.');

