 "value": {"op":"case","when":[{"if":{"op":"=","args":[{"var":"boundary_type"},"PRIMARY_FRONTAGE"]},"then":6}],"else":3},
 "unit": "m",
 "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT",
 "verification": "VERIFIED_VERBATIM",
 "automatable": true,
 "scopes": [{"level":"LOCAL_GOVERNMENT","lg":"LIVINGSTONE"},{"level":"LOCAL_PLAN_PRECINCT","local_plan_precinct":"LSC:SEASPRAY/SEASPRAY_RESIDENTIAL_LOW_DENSITY"},{"level":"LOCAL_PLAN_PRECINCT","local_plan_precinct":"LSC:SEASPRAY/SEASPRAY_RESIDENTIAL_MEDIUM_DENSITY"}],
 "subjects": ["ANY",{"id":"FENCE","exclude":true},{"id":"POOL_BARRIER","exclude":true}],
 "conditions": [[{"fact":"development_footprint_exists","op":"IS_FALSE"},{"fact":"boundary_type","op":"IN","value":["PRIMARY_FRONTAGE","SECONDARY_FRONTAGE_ROAD"]}]],
 "sources": [{"key":"lsc_seaspray_res_front","role":"PRIMARY","quote":"AO5.1 Buildings or structures (other than fences) have a setback from road frontage lot boundaries in accordance with the following: ... (b) where located in the Seaspray Residential Low Density Precinct or the Seaspray Residential Medium Density Precinct and the lot does not have an approved building location envelope: (i) a setback from the primary road frontage lot boundary of at least six (6) metres; and (ii) a setback from a secondary road frontage lot boundary of at least three (3) metres;"}],
 "interpretation_notes": "Pool barriers treated as fences. No approved building location envelope (BLE) read as development_footprint_exists = false; where a BLE exists the development must be within it (not encoded). Fences excluded by the text. The local plan code prevails over zone codes (s1.5(d)), so these rules OVERRIDE every zone-based LSC.C setback rule; the underlying zone of the Seaspray area was not confirmed by the research, which this makes immaterial.",
 "effective_from": "2025-05-02"}$r$);
