SELECT alt_overrides('LSC.C.SEASPRAY_RES_FRONT@2025-05-02', ARRAY['QDC12.A1a.ROAD_SETBACK','QDC11.A1a.FRONTAGE_SETBACK'], 'Part 1 s1.6(4)(e): the Seaspray Local Plan is a building assessment provision (s33 alternative boundary clearance); Table 5.8.1.5 makes standalone Class 10a building work accepted subject to requirements against AO5.1/AO5.2.');

SELECT define_rule($r${
 "rule_id": "LSC.C.SEASPRAY_RES_SIDE_REAR_1_5M",
