SELECT alt_overrides('LSC.C.SEASPRAY_RES_SIDE_REAR_1_5M@2025-05-02', ARRAY['QDC12.A2a.SIDE_REAR_CLEARANCE','QDC11.A2a.SIDE_REAR_CLEARANCE','QDC12.A2b.NARROW_LOT_CLEARANCE','QDC11.A2b.NARROW_LOT_CLEARANCE','QDC12.A2d.CLASS10A_WITHIN_CLEARANCE','QDC11.A2d.CLASS10A_WITHIN_CLEARANCE'], 'Part 1 s1.6(4)(e): the Seaspray Local Plan is a building assessment provision (s33 alternative boundary clearance); Table 5.8.1.5 makes standalone Class 10a building work accepted subject to requirements against AO5.1/AO5.2. AO5.2 has no Class 10a concession, displacing QDC A2(d).');

