SELECT define_rule($r${
 "rule_id": "LSC.C.SEASPRAY_COMREC_SIDE_REAR_10M",
 "instrument_version": "LSC_PLANNING_SCHEME_2018@2025-05-02",
 "topic": "SETBACK.SIDE_REAR",
 "title": "Seaspray Community and Recreation precinct (no BLE): buildings or structures other than fences 10 m from side and rear boundaries (+0.3 m per metre over 4.5 m)",
 "role": "REQUIREMENT",
 "regime": "BUILDING",
 "enforceability": "DEEMED_TO_COMPLY",
 "provision_kind": "ACCEPTABLE_OUTCOME",
 "measurement": "SCHEME_SETBACK_SIDE",
 "operator": ">=",
 "value": {"op":"case","when":[{"if":{"op":"<=","args":[{"var":"part_height_m"},4.5]},"then":10}],"else":{"op":"+","args":[10,{"op":"*","args":[0.3,{"op":"ceil","args":[{"op":"-","args":[{"var":"part_height_m"},4.5]}]}]}]}},
 "unit": "m",
 "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT",
 "verification": "VERIFIED_VERBATIM",
 "automatable": true,
 "scopes": [{"level":"LOCAL_GOVERNMENT","lg":"LIVINGSTONE"},{"level":"LOCAL_PLAN_PRECINCT","local_plan_precinct":"LSC:SEASPRAY/SEASPRAY_COMMUNITY_AND_RECREATION"}],
 "subjects": ["ANY",{"id":"FENCE","exclude":true},{"id":"POOL_BARRIER","exclude":true}],
 "conditions": [[{"fact":"development_footprint_exists","op":"IS_FALSE"},{"fact":"structure_height_m","op":">","value":2},{"fact":"boundary_type","op":"IN","value":["SIDE","REAR"]}]],
 "sources": [{"key":"lsc_seaspray_comrec_side_rear","role":"PRIMARY","quote":"AO5.2 Buildings or structures (other than fences) have a setback from side and rear lot boundaries in accordance with the following: ... (c) where located in the Seaspray Community and Recreation Precinct and the lot does not have an approved building location envelope: (i) at any point where the ‘outermost projection height’ is between two (2) metres and 4.5 metres, a setback of at least ten (10) metres; or (ii) at any point where the ‘outermost projection height’ is greater than 4.5 metres, a setback of at least ten (10) metres plus 0.3 of a metre for every additional metre or part thereof in height over 4.5 metres."}],
 "interpretation_notes": "Per part: part_height_m = outermost projection height; 'part thereof' => ceil. No requirement below 2 m: rule applies only to structures over 2 m. Pool barriers treated as fences. No approved building location envelope (BLE) read as development_footprint_exists = false; where a BLE exists the development must be within it (not encoded). Fences excluded by the text. The local plan code prevails over zone codes (s1.5(d)), so these rules OVERRIDE every zone-based LSC.C setback rule; the underlying zone of the Seaspray area was not confirmed by the research, which this makes immaterial.",
 "effective_from": "2025-05-02"}$r$);
SELECT supersede_draft('LSC.C.SEASPRAY_COMREC_SIDE_REAR_10M@2025-05-02', 'LSC.lsc_seaspray_comrec_side_rear');
SELECT alt_overrides('LSC.C.SEASPRAY_COMREC_SIDE_REAR_10M@2025-05-02', ARRAY['QDC12.A2a.SIDE_REAR_CLEARANCE','QDC11.A2a.SIDE_REAR_CLEARANCE','QDC12.A2b.NARROW_LOT_CLEARANCE','QDC11.A2b.NARROW_LOT_CLEARANCE','QDC12.A2d.CLASS10A_WITHIN_CLEARANCE','QDC11.A2d.CLASS10A_WITHIN_CLEARANCE'], 'Part 1 s1.6(4)(e): the Seaspray Local Plan is a building assessment provision (s33 alternative boundary clearance); Table 5.8.1.5 makes standalone Class 10a building work accepted subject to requirements against AO5.1/AO5.2.');

INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, verification, notes)
SELECT f, r.rule_id, 'OVERRIDES', 'VERIFIED_VERBATIM', 'Seaspray local plan code prevails over the zone codes (s1.5(d)); Table 5.8.1.5 assesses building work in the local plan area against AO5.1/AO5.2.'
FROM unnest(ARRAY['LSC.C.SEASPRAY_RES_FRONT@2025-05-02','LSC.C.SEASPRAY_RES_SIDE_REAR_1_5M@2025-05-02','LSC.C.SEASPRAY_COMREC_FRONT_6M@2025-05-02','LSC.C.SEASPRAY_COMREC_SIDE_REAR_10M@2025-05-02']) f
JOIN rules r ON r.rule_id LIKE 'LSC.C.%' AND r.rule_id NOT LIKE 'LSC.C.SEASPRAY%' AND r.rule_id NOT LIKE 'LSC.C.SCH10%';

