SELECT define_rule($r${
 "rule_id": "LSC.C.SCH10_LOW_STRUCTURE_FRONT_EXEMPT",
 "instrument_version": "LSC_PLANNING_SCHEME_2018@2025-05-02",
 "topic": "SETBACK.FRONTAGE",
 "title": "Schedule 10: building or structure (or combination, e.g. fence on a retaining wall) not over 2 m high exempt from the road frontage setback",
 "role": "EXEMPTION",
 "regime": "BUILDING",
 "enforceability": "DEEMED_TO_COMPLY",
 "provision_kind": "ACCEPTABLE_OUTCOME",
 "verification": "VERIFIED_VERBATIM",
 "automatable": true,
 "scopes": [{"level":"LOCAL_GOVERNMENT","lg":"LIVINGSTONE"},{"level":"ZONE","zone":"LSC:RURAL"},{"level":"ZONE","zone":"LSC:EMERGING_COMMUNITY"},{"level":"ZONE","zone":"LSC:LOW_DENSITY_RESIDENTIAL"},{"level":"ZONE","zone":"LSC:LOW_MEDIUM_DENSITY_RESIDENTIAL"},{"level":"ZONE","zone":"LSC:TOWNSHIP"},{"level":"ZONE","zone":"LSC:MEDIUM_DENSITY_RESIDENTIAL"},{"level":"PRECINCT","precinct":"LSC:MAJOR_TOURISM/CAPRICORN_INTERNATIONAL_RESORT"},{"level":"PRECINCT","precinct":"LSC:MAJOR_TOURISM/GREAT_KEPPEL_ISLAND"},{"level":"ZONE","zone":"LSC:RURAL_RESIDENTIAL"}],
 "subjects": ["ANY"],
 "conditions": [[{"fact":"boundary_type","op":"IN","value":["PRIMARY_FRONTAGE","SECONDARY_FRONTAGE_ROAD"]},{"fact":"structure_height_m","op":"<=","value":2}]],
 "sources": [{"key":"lsc_rur_ec_lt3000_front_class10a","role":"PRIMARY","quote":"Circumstance (E): A building or structure that: (a) if standalone, does not have an ‘outermost projection height’ exceeding two (2) metres; or (b) if involving a combination with other buildings or structures, does not result in a combined height exceeding two (2) metres."},{"key":"lsc_ldr_lmdr_twp_front_class10a","role":"SUPPLEMENTARY","quote":"Circumstance (E): A building or structure that: (a) if standalone, does not have an ‘outermost projection height’ exceeding two (2) metres; or (b) if involving a combination with other buildings or structures, does not result in a combined height exceeding two (2) metres."},{"key":"lsc_mdr_mt_front_class10a","role":"SUPPLEMENTARY","quote":"Circumstance (E): A building or structure that: (a) if standalone, does not have an ‘outermost projection height’ exceeding two (2) metres; or (b) if involving a combination with other buildings or structures, does not result in a combined height exceeding two (2) metres."},{"key":"lsc_rur_ec_3000_9999_front","role":"SUPPLEMENTARY","quote":"Circumstance (C): A building or structure that: (a) if standalone, does not have an ‘outermost projection height’ exceeding two (2) metres; or (b) if involving a combination with other buildings or structures, does not result in a combined height exceeding two (2) metres."},{"key":"lsc_rur_ec_1ha_5ha_front","role":"SUPPLEMENTARY","quote":"Circumstance (C): A building or structure that does not have an ‘outermost projection height’ exceeding two (2) metres."},{"key":"lsc_rr_prp_or_lt1ha_front","role":"SUPPLEMENTARY","quote":"Circumstance (C): A building or structure that: (a) if standalone, does not have an ‘outermost projection height’ exceeding two (2) metres; or (b) if involving a combination with other buildings or structures, does not result in a combined height exceeding two (2) metres."}],
 "interpretation_notes": "structure_height_m = overall height of the structure, or of the combination (fence plus retaining wall) where combined. Exempts the Schedule 10 road frontage rules (not Yaamba or Seaspray, which have no such circumstance).",
 "effective_from": "2025-05-02"}$r$);

